const TRUEFACE_WASM_BASE64 = "";

/**
 * TrueFace Web SDK
 * Lightweight, secure biometric liveness and face matching SDK for browsers with MediaPipe FaceLandmarker.
 */
class TrueFaceLiveness {
  constructor(config) {
    config = config || {};
    this.backendBaseUrl = config.backendBaseUrl ? config.backendBaseUrl.replace(/\/$/, '') : 'https://api.trueface.dev';
    this.grpcBaseUrl = config.grpcBaseUrl ? config.grpcBaseUrl.replace(/\/$/, '') : 'https://realtime.trueface.dev';
    this.publicKey = config.publicKey;
    this.verificationId = config.verificationId;
    this.clientSecret = config.clientSecret;
    this.challenges = [];
    this.completedChallenges = [];

    this.grpcSessionId = null;
    this.grpcProofToken = null;
    this.frameCount = 0;

    this.stream = null;
    this.mediaRecorder = null;
    this.recordedChunks = [];
    this.videoElement = null;
    this.container = null;
    this.overlayElement = null;
    this.ovalElement = null;
    this.stepBadgeElement = null;
    this.promptElement = null;
    this.progressBar = null;

    // MediaPipe & WebAssembly state
    this.faceLandmarker = null;
    this.isMediaPipeReady = false;
    this.wasmInstance = null;
    this.animFrameId = null;

    this.showInstructions = config.showInstructions !== undefined ? config.showInstructions : null;
    this.serverShowInstructions = true;

    this.resolvePromise = null;
    this.rejectPromise = null;
  }

  /**
   * Mounts the camera preview and starts the liveness check sequence.
   */
  async start(containerElement) {
    this.container = containerElement;
    this.container.classList.add('trueface-container');

    // 1. Setup UI elements
    this._createUI();

    return new Promise(async (resolve, reject) => {
      this.resolvePromise = resolve;
      this.rejectPromise = reject;

      try {
        this.overlayElement.style.display = 'flex';

        // Check if pre-session instructions screen should be shown BEFORE opening camera
        const shouldShowInstructions = this.showInstructions !== null
          ? this.showInstructions
          : this.serverShowInstructions;

        if (shouldShowInstructions) {
          await this._showInstructionsUI();
        }

        this._updateStatus('Initializing camera & security module...', 'PREPARING');

        // Start Wasm and MediaPipe initialization in parallel with camera setup
        const wasmPromise = this._initWasm();
        const mediaPipePromise = this._initMediaPipe();

        // Start webcam stream AFTER user acknowledges instructions
        this.stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user', width: { ideal: 640 }, height: { ideal: 480 } },
          audio: false
        });

        this.videoElement.srcObject = this.stream;
        await this.videoElement.play();

        await Promise.all([wasmPromise, mediaPipePromise]);

        const maxAttempts = 3;
        let attempt = 0;

        while (attempt < maxAttempts) {
          attempt++;
          try {
            this.completedChallenges = [];
            this.capturedImageBase64 = null;
            this._updateStatus('Starting session...', 'INITIALIZING');
            await this._startSession();

            // 2. Initial Face Framing check
            await this._waitForFaceFraming();

            // 3. Start Media Recording
            this._startRecording();

            // 4. Run Active Challenges Flow
            await this._runChallenges();

            // 5. Final Straight-Face Alignment
            await this._waitForStraightFace();

            // 6. Replace camera scanner with Processing Loader UI
            this._showProcessingUI();

            // 7. Finalize and Upload data via gRPC
            await this._finalizeAndUpload();

            // 8. Complete Verification
            const result = await this._completeVerification();

            // 9. Display Outcome Card (so box displays result instead of going blank)
            this._showOutcomeUI(result);

            await new Promise(r => setTimeout(r, 1800));

            this.cleanup();
            resolve(result);
            return;
          } catch (err) {
            if (err.message === 'LIVENESS_CHALLENGES_INCOMPLETE' && attempt < maxAttempts) {
              console.warn(`[TrueFace SDK] Biometric challenges incomplete (Attempt ${attempt}/${maxAttempts}). Restarting challenges...`);
              this._updateStatus('⚠️ Biometric check incomplete — restarting challenges...', 'RESTARTING');
              if (this.mediaRecorder && this.mediaRecorder.state !== 'inactive') {
                try { this.mediaRecorder.stop(); } catch (e) { }
              }
              await new Promise(r => setTimeout(r, 2000));
              continue;
            }
            throw err;
          }
        }
      } catch (err) {
        this.cleanup();
        this._showError(err.message || String(err));
        reject(err);
      }
    });
  }

  /**
   * Stops camera streams and MediaPipe loops.
   */
  cleanup() {
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
    if (this.stream) {
      this.stream.getTracks().forEach(track => track.stop());
      this.stream = null;
    }
    if (this.mediaRecorder && this.mediaRecorder.state !== 'inactive') {
      try { this.mediaRecorder.stop(); } catch (e) { }
    }
  }

  /**
   * Loads and initializes Google MediaPipe FaceLandmarker via CDN or global bundle.
   */
  async _initMediaPipe() {
    try {
      let FaceLandmarker, FilesetResolver;
      if (window.vision) {
        FaceLandmarker = window.vision.FaceLandmarker;
        FilesetResolver = window.vision.FilesetResolver;
      } else {
        // Dynamically import official MediaPipe tasks-vision ES module
        const visionModule = await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/+esm');
        FaceLandmarker = visionModule.FaceLandmarker;
        FilesetResolver = visionModule.FilesetResolver;
      }

      const filesetResolver = await FilesetResolver.forVisionTasks(
        'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14/wasm'
      );

      this.faceLandmarker = await FaceLandmarker.createFromOptions(filesetResolver, {
        baseOptions: {
          modelAssetPath: 'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task',
          delegate: 'GPU'
        },
        runningMode: 'VIDEO',
        numFaces: 3 // Track up to 3 faces to detect multi-person spoof attempts
      });

      this.isMediaPipeReady = true;
      console.log('[TrueFace SDK] MediaPipe FaceLandmarker initialized successfully.');
    } catch (err) {
      console.warn('[TrueFace SDK] MediaPipe initialization failed. Falling back to timer mode:', err);
      this.isMediaPipeReady = false;
    }
  }

  _createUI() {
    this.overlayElement = document.createElement('div');
    this.overlayElement.className = 'trueface-overlay';

    // Camera Viewport Box
    const viewport = document.createElement('div');
    viewport.className = 'trueface-viewport';

    this.videoElement = document.createElement('video');
    this.videoElement.className = 'trueface-video';
    this.videoElement.setAttribute('autoplay', '');
    this.videoElement.setAttribute('playsinline', '');
    this.videoElement.muted = true;

    // Oval Target Overlay
    this.ovalElement = document.createElement('div');
    this.ovalElement.className = 'trueface-oval-guide';
    const scanner = document.createElement('div');
    scanner.className = 'trueface-scanner-line';
    this.ovalElement.appendChild(scanner);

    viewport.appendChild(this.videoElement);
    viewport.appendChild(this.ovalElement);

    // Prompts and Guidance Panel
    const panel = document.createElement('div');
    panel.className = 'trueface-guidance-panel';

    this.stepBadgeElement = document.createElement('div');
    this.stepBadgeElement.className = 'trueface-step-badge';
    this.stepBadgeElement.textContent = 'STEP 0/0';

    this.promptElement = document.createElement('p');
    this.promptElement.className = 'trueface-prompt';
    this.promptElement.textContent = 'Align your face in the oval target';

    // Progress Bar wrapper
    const progressWrapper = document.createElement('div');
    progressWrapper.className = 'trueface-progress-wrapper';
    this.progressBar = document.createElement('div');
    this.progressBar.className = 'trueface-progress-bar';
    this.progressBar.style.width = '0%';
    progressWrapper.appendChild(this.progressBar);

    panel.appendChild(this.stepBadgeElement);
    panel.appendChild(this.promptElement);
    panel.appendChild(progressWrapper);

    // Position Viewport full-bleed, Guidance Panel floating at top
    this.overlayElement.appendChild(viewport);
    this.overlayElement.appendChild(panel);
    this.container.appendChild(this.overlayElement);
  }

  _updateStatus(text, stepText = '') {
    if (this.promptElement) {
      this.promptElement.textContent = text;
    }
    if (stepText && this.stepBadgeElement) {
      this.stepBadgeElement.textContent = stepText;
    }
  }

  _updateProgress(percent) {
    if (this.progressBar) {
      this.progressBar.style.width = `${percent}%`;
    }
  }

  async _startSession() {
    const res = await fetch(`${this.backendBaseUrl}/v1/sessions/${this.verificationId}/start`, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-public-key': this.publicKey,
        'x-client-secret': this.clientSecret
      },
      body: JSON.stringify({ clientSecret: this.clientSecret })
    });
    if (!res.ok) throw new Error(`Failed to start liveness session (${res.status})`);
    const data = await res.json();
    this.challenges = data.challenges || ['blink', 'smile', 'turnLeft'];
    if (data.showInstructions !== undefined) {
      this.serverShowInstructions = data.showInstructions;
    }

    // Start gRPC Real-Time Liveness Stream Session
    await this._initGrpcSession();
  }

  _showInstructionsUI() {
    return new Promise((resolve) => {
      const card = document.createElement('div');
      card.className = 'trueface-instructions-card';
      card.innerHTML = `
        <div class="trueface-instructions-header">
          <div class="trueface-instructions-title">Liveness Check</div>
          <div class="trueface-instructions-sub">Follow these simple tips for a fast verification:</div>
        </div>

        <div class="trueface-tips-list">
          <div class="trueface-tip-item">
            <div class="trueface-tip-icon">☀️</div>
            <div>
              <div class="trueface-tip-text-title">Good Lighting</div>
              <div class="trueface-tip-text-sub">Face a light source without strong backlights or dark shadows.</div>
            </div>
          </div>
          <div class="trueface-tip-item">
            <div class="trueface-tip-icon">👓</div>
            <div>
              <div class="trueface-tip-text-title">Clear Visibility</div>
              <div class="trueface-tip-text-sub">Remove sunglasses, heavy hats, or facial coverings.</div>
            </div>
          </div>
          <div class="trueface-tip-item">
            <div class="trueface-tip-icon">🎯</div>
            <div>
              <div class="trueface-tip-text-title">Center Your Face</div>
              <div class="trueface-tip-text-sub">Keep your head inside the guide oval during prompts.</div>
            </div>
          </div>
        </div>

        <button class="trueface-start-btn">I'm Ready — Start Check</button>
      `;

      const btn = card.querySelector('.trueface-start-btn');
      btn.addEventListener('click', () => {
        card.remove();
        resolve();
      });

      if (this.overlayElement) {
        this.overlayElement.appendChild(card);
      } else {
        resolve();
      }
    });
  }

  // --- Protobuf Binary Wire Encoding & gRPC-Web Framing Helpers ---

  _encodeVarint(val) {
    const bytes = [];
    let num = Number(val);
    if (isNaN(num)) num = 0;
    while (num >= 0x80) {
      bytes.push((num & 0x7f) | 0x80);
      num = Math.floor(num / 128);
    }
    bytes.push(num & 0x7f);
    return bytes;
  }

  _encodeTag(fieldNum, wireType) {
    return this._encodeVarint((fieldNum << 3) | wireType);
  }

  _encodeString(fieldNum, str) {
    if (!str) return [];
    const encoder = new TextEncoder();
    const strBytes = Array.from(encoder.encode(str));
    const tag = this._encodeTag(fieldNum, 2);
    const lenVarint = this._encodeVarint(strBytes.length);
    return [...tag, ...lenVarint, ...strBytes];
  }

  _encodeBytes(fieldNum, uint8Arr) {
    if (!uint8Arr || uint8Arr.length === 0) return [];
    const bytes = Array.from(uint8Arr);
    const tag = this._encodeTag(fieldNum, 2);
    const lenVarint = this._encodeVarint(bytes.length);
    return [...tag, ...lenVarint, ...bytes];
  }

  _encodeInt64(fieldNum, val) {
    const tag = this._encodeTag(fieldNum, 0);
    const varint = this._encodeVarint(val || 0);
    return [...tag, ...varint];
  }

  _encodeInt32(fieldNum, val) {
    const tag = this._encodeTag(fieldNum, 0);
    const varint = this._encodeVarint(val || 0);
    return [...tag, ...varint];
  }

  _encodeDouble(fieldNum, val) {
    const tag = this._encodeTag(fieldNum, 1);
    const buf = new ArrayBuffer(8);
    new DataView(buf).setFloat64(0, Number(val) || 0, true);
    return [...tag, ...Array.from(new Uint8Array(buf))];
  }

  _formatGrpcWebPayload(protoBytes) {
    const len = protoBytes.length;
    const header = new Uint8Array(5);
    header[0] = 0x00;
    header[1] = (len >> 24) & 0xff;
    header[2] = (len >> 16) & 0xff;
    header[3] = (len >> 8) & 0xff;
    header[4] = len & 0xff;
    const full = new Uint8Array(5 + len);
    full.set(header, 0);
    full.set(protoBytes, 5);
    return full;
  }

  _readVarint(bytes, offset) {
    let res = 0;
    let shift = 0;
    let idx = offset;
    while (idx < bytes.length) {
      const b = bytes[idx++];
      res |= (b & 0x7f) << shift;
      if ((b & 0x80) === 0) break;
      shift += 7;
    }
    return { val: res, next: idx };
  }

  _skipWireField(bytes, idx, wireType) {
    if (wireType === 0) {
      return this._readVarint(bytes, idx).next;
    } else if (wireType === 1) {
      return idx + 8;
    } else if (wireType === 2) {
      const lenObj = this._readVarint(bytes, idx);
      return lenObj.next + lenObj.val;
    } else if (wireType === 5) {
      return idx + 4;
    }
    return bytes.length;
  }

  _decodeStartSessionResponse(bytes) {
    if (bytes.length >= 5 && bytes[0] === 0x00) {
      bytes = bytes.subarray(5);
    }
    const res = { session_id: '', expires_at_ms: 0, allowed_challenges: [] };
    let idx = 0;
    while (idx < bytes.length) {
      const v = this._readVarint(bytes, idx);
      if (v.next === idx) break;
      idx = v.next;
      const fieldNum = v.val >> 3;
      const wireType = v.val & 0x07;
      if (fieldNum === 1 && wireType === 2) {
        const lenObj = this._readVarint(bytes, idx);
        idx = lenObj.next;
        const strBytes = bytes.subarray(idx, idx + lenObj.val);
        res.session_id = new TextDecoder().decode(strBytes);
        idx += lenObj.val;
      } else if (fieldNum === 2 && wireType === 0) {
        const valObj = this._readVarint(bytes, idx);
        idx = valObj.next;
        res.expires_at_ms = valObj.val;
      } else if (fieldNum === 3 && wireType === 0) {
        const valObj = this._readVarint(bytes, idx);
        idx = valObj.next;
        res.allowed_challenges.push(valObj.val);
      } else {
        idx = this._skipWireField(bytes, idx, wireType);
      }
    }
    return res;
  }

  _decodeCompleteSessionResponse(bytes) {
    if (bytes.length >= 5 && bytes[0] === 0x00) {
      bytes = bytes.subarray(5);
    }
    const res = { proof_token: '', is_approved: false, completed_at_ms: 0, decision_reason: '', image_key: '', video_key: '' };
    let idx = 0;
    while (idx < bytes.length) {
      const v = this._readVarint(bytes, idx);
      if (v.next === idx) break;
      idx = v.next;
      const fieldNum = v.val >> 3;
      const wireType = v.val & 0x07;
      if (fieldNum === 1 && wireType === 2) {
        const lenObj = this._readVarint(bytes, idx);
        idx = lenObj.next;
        res.proof_token = new TextDecoder().decode(bytes.subarray(idx, idx + lenObj.val));
        idx += lenObj.val;
      } else if (fieldNum === 2 && wireType === 0) {
        const valObj = this._readVarint(bytes, idx);
        idx = valObj.next;
        res.is_approved = valObj.val === 1;
      } else if (fieldNum === 3 && wireType === 0) {
        const valObj = this._readVarint(bytes, idx);
        idx = valObj.next;
        res.completed_at_ms = valObj.val;
      } else if (fieldNum === 4 && wireType === 2) {
        const lenObj = this._readVarint(bytes, idx);
        idx = lenObj.next;
        res.decision_reason = new TextDecoder().decode(bytes.subarray(idx, idx + lenObj.val));
        idx += lenObj.val;
      } else if (fieldNum === 5 && wireType === 2) {
        const lenObj = this._readVarint(bytes, idx);
        idx = lenObj.next;
        res.image_key = new TextDecoder().decode(bytes.subarray(idx, idx + lenObj.val));
        idx += lenObj.val;
      } else if (fieldNum === 6 && wireType === 2) {
        const lenObj = this._readVarint(bytes, idx);
        idx = lenObj.next;
        res.video_key = new TextDecoder().decode(bytes.subarray(idx, idx + lenObj.val));
        idx += lenObj.val;
      } else {
        idx = this._skipWireField(bytes, idx, wireType);
      }
    }
    return res;
  }

  async _initGrpcSession() {
    try {
      const protoBytes = [
        ...this._encodeString(1, this.verificationId),
        ...this._encodeString(2, this.clientSecret)
      ];
      const payload = this._formatGrpcWebPayload(new Uint8Array(protoBytes));

      const res = await fetch(`${this.grpcBaseUrl}/liveness.LivenessService/StartSession`, {
        method: 'POST',
        headers: { 'content-type': 'application/grpc-web+proto' },
        body: payload
      });
      if (res.ok) {
        const buf = new Uint8Array(await res.arrayBuffer());
        const data = this._decodeStartSessionResponse(buf);
        this.grpcSessionId = data.session_id;
        console.log('[TrueFace SDK] gRPC-Web Binary Session Started:', this.grpcSessionId, data.allowed_challenges);

        if (Array.isArray(data.allowed_challenges) && data.allowed_challenges.length > 0) {
          const protoToName = {
            1: 'alignFace',
            2: 'blink',
            3: 'smile',
            4: 'turnLeft',
            5: 'turnRight',
            6: 'lookStraight',
            7: 'openMouth'
          };
          const mapped = data.allowed_challenges
            .map(c => protoToName[c])
            .filter(c => c && c !== 'alignFace' && c !== 'lookStraight');
          if (mapped.length > 0) {
            this.challenges = mapped;
          }
        }
      }
    } catch (err) {
      console.warn('[TrueFace SDK] gRPC Liveness Service connection fallback:', err);
    }
  }

  async _sendGrpcFrame(ear, smile, yaw, mar) {
    if (!this.grpcSessionId) return;
    this.frameCount++;
    try {
      const protoBytes = [
        ...this._encodeString(1, this.grpcSessionId),
        ...this._encodeInt64(2, this.frameCount),
        ...this._encodeInt64(3, Date.now()),
        ...this._encodeString(4, Math.random().toString(36).substring(2)),
        ...this._encodeInt32(5, 0),
        ...this._encodeDouble(6, ear || 0),
        ...this._encodeDouble(7, smile || 0),
        ...this._encodeDouble(8, yaw || 0.5),
        ...this._encodeDouble(9, 0),
        ...this._encodeDouble(10, mar || 0),
        ...this._encodeInt32(11, 1)
      ];
      const payload = this._formatGrpcWebPayload(new Uint8Array(protoBytes));

      fetch(`${this.grpcBaseUrl}/liveness.LivenessService/StreamLiveness`, {
        method: 'POST',
        headers: { 'content-type': 'application/grpc-web+proto' },
        body: payload
      }).catch(() => { });
    } catch (err) {
      // silent
    }
  }

  async _sendGrpcVideoChunk(base64Chunk) {
    if (!this.grpcSessionId) return;
    try {
      let vidChunkBytes = [];
      if (base64Chunk) {
        const bin = atob(base64Chunk);
        vidChunkBytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) vidChunkBytes[i] = bin.charCodeAt(i);
      }
      const protoBytes = [
        ...this._encodeString(1, this.grpcSessionId),
        ...this._encodeInt64(2, this.frameCount),
        ...this._encodeInt64(3, Date.now()),
        ...this._encodeString(4, Math.random().toString(36).substring(2)),
        ...this._encodeInt32(5, 0),
        ...this._encodeDouble(6, 0),
        ...this._encodeDouble(7, 0),
        ...this._encodeDouble(8, 0.5),
        ...this._encodeDouble(9, 0),
        ...this._encodeDouble(10, 0),
        ...this._encodeInt32(11, 1),
        ...this._encodeString(12, ""),
        ...this._encodeBytes(13, []),
        ...this._encodeBytes(14, vidChunkBytes)
      ];
      const payload = this._formatGrpcWebPayload(new Uint8Array(protoBytes));

      fetch(`${this.grpcBaseUrl}/liveness.LivenessService/StreamLiveness`, {
        method: 'POST',
        headers: { 'content-type': 'application/grpc-web+proto' },
        body: payload
      }).catch(() => { });
    } catch (err) {
      // silent
    }
  }

  async _completeGrpcSession(finalImageBase64, finalVideoBase64) {
    if (!this.grpcSessionId) return null;
    try {
      let imgBytes = [];
      if (finalImageBase64) {
        const bin = atob(finalImageBase64);
        imgBytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) imgBytes[i] = bin.charCodeAt(i);
      }
      let vidBytes = [];
      if (finalVideoBase64) {
        const bin = atob(finalVideoBase64);
        vidBytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) vidBytes[i] = bin.charCodeAt(i);
      }

      const protoBytes = [
        ...this._encodeString(1, this.grpcSessionId),
        ...this._encodeString(2, this.verificationId),
        ...this._encodeBytes(3, imgBytes),
        ...this._encodeBytes(4, vidBytes)
      ];
      const payload = this._formatGrpcWebPayload(new Uint8Array(protoBytes));

      const res = await fetch(`${this.grpcBaseUrl}/liveness.LivenessService/CompleteSession`, {
        method: 'POST',
        headers: { 'content-type': 'application/grpc-web+proto' },
        body: payload
      });
      if (res.ok) {
        const buf = new Uint8Array(await res.arrayBuffer());
        const data = this._decodeCompleteSessionResponse(buf);
        if (data.proof_token && data.is_approved) {
          this.grpcProofToken = data.proof_token;
          if (data.image_key) this.imageKey = data.image_key;
          if (data.video_key) this.videoKey = data.video_key;
          console.log('[TrueFace SDK] Cryptographic gRPC-Web Binary Proof Token & Keys Received:', this.imageKey, this.videoKey);
          return data;
        } else {
          console.warn('[TrueFace SDK] gRPC Liveness incomplete:', data.decision_reason);
          return data;
        }
      }
    } catch (err) {
      console.warn('[TrueFace SDK] Could not complete gRPC liveness session:', err);
    }
    return null;
  }

  _startRecording() {
    this.recordedChunks = [];
    if (!this.stream || !(this.stream instanceof MediaStream) || !this.stream.active) {
      console.warn('[TrueFace SDK] Cannot start MediaRecorder: MediaStream is missing or inactive.');
      return;
    }
    try {
      let options;
      if (typeof MediaRecorder !== 'undefined' && typeof MediaRecorder.isTypeSupported === 'function') {
        if (MediaRecorder.isTypeSupported('video/webm;codecs=vp8')) {
          options = { mimeType: 'video/webm;codecs=vp8' };
        } else if (MediaRecorder.isTypeSupported('video/webm')) {
          options = { mimeType: 'video/webm' };
        } else if (MediaRecorder.isTypeSupported('video/mp4')) {
          options = { mimeType: 'video/mp4' };
        }
      }
      this.mediaRecorder = options ? new MediaRecorder(this.stream, options) : new MediaRecorder(this.stream);
    } catch (e) {
      console.warn('[TrueFace SDK] MediaRecorder initialization failed:', e);
      this.mediaRecorder = null;
      return;
    }

    if (!this.mediaRecorder) return;

    this.mediaRecorder.ondataavailable = async (e) => {
      if (e.data && e.data.size > 0) {
        this.recordedChunks.push(e.data);
        if (this.grpcSessionId) {
          try {
            const buffer = await e.data.arrayBuffer();
            const bytes = new Uint8Array(buffer);
            let binary = '';
            for (let i = 0; i < bytes.byteLength; i++) {
              binary += String.fromCharCode(bytes[i]);
            }
            const base64Chunk = btoa(binary);
            this._sendGrpcVideoChunk(base64Chunk);
          } catch (err) {
            // silent
          }
        }
      }
    };
    try {
      this.mediaRecorder.start(400);
    } catch (err) {
      console.warn('[TrueFace SDK] Error starting MediaRecorder:', err);
    }
  }

  /**
   * Waits until user frames their face properly inside the target oval.
   * Ensures video recording is NOT started until a face is detected and positioned correctly.
   */
  async _waitForFaceFraming() {
    // 1. Wait for MediaPipe to be ready if still initializing
    let attempts = 0;
    while ((!this.isMediaPipeReady || !this.faceLandmarker) && attempts < 50) {
      await new Promise(r => setTimeout(r, 100));
      attempts++;
    }

    if (!this.isMediaPipeReady || !this.faceLandmarker) {
      console.warn('[TrueFace SDK] MediaPipe unavailable for face framing check.');
      return;
    }

    this._updateStatus('Position your face inside the oval target', 'POSITION FACE');
    this.ovalElement.classList.remove('valid', 'action', 'error');

    return new Promise((resolve) => {
      let framedFramesCount = 0;

      const checkFraming = () => {
        if (!this.stream || !this.videoElement) {
          resolve();
          return;
        }

        const results = this.faceLandmarker.detectForVideo(this.videoElement, performance.now());
        const count = results.faceLandmarks ? results.faceLandmarks.length : 0;

        if (count > 1) {
          framedFramesCount = 0;
          this.ovalElement.classList.remove('valid', 'action');
          this.ovalElement.classList.add('error');
          this._updateStatus('⚠️ Multiple faces detected. Only 1 face allowed.', 'MULTIPLE FACES');
        } else if (count === 0) {
          framedFramesCount = 0;
          this.ovalElement.classList.remove('valid', 'action', 'error');
          this._updateStatus('Position your face inside the oval target', 'POSITION FACE');
        } else {
          const landmarks = results.faceLandmarks[0];
          const pos = this._evaluateFacePosition(landmarks);

          if (!pos.isGood) {
            framedFramesCount = 0;
            this.ovalElement.classList.remove('valid', 'action');
            this.ovalElement.classList.add('error');
            this._updateStatus(pos.hint, 'ALIGNMENT');
          } else {
            framedFramesCount++;
            this.ovalElement.classList.remove('error', 'action');
            this.ovalElement.classList.add('valid');
            this._updateStatus('✔ Face detected! Hold still...', 'FACE READY');

            // Must hold face in position for 8 consecutive frames (~250-300ms) before starting video recording
            if (framedFramesCount >= 8) {
              setTimeout(resolve, 100);
              return;
            }
          }
        }

        this.animFrameId = requestAnimationFrame(checkFraming);
      };

      checkFraming();
    });
  }

  /**
   * Runs active liveness challenges using real-time MediaPipe gesture evaluation.
   */
  async _runChallenges() {
    const total = this.challenges.length;

    for (let i = 0; i < total; i++) {
      const challenge = this.challenges[i];
      const stepLabel = `STEP ${i + 1}/${total}`;
      const instructions = {
        blink: 'Blink your eyes now',
        smile: 'Smile directly at the camera',
        turnLeft: 'Turn your face to the Left',
        turnRight: 'Turn your face to the Right',
        openMouth: 'Open your mouth wide',
      };

      this.ovalElement.classList.remove('valid', 'error');
      this.ovalElement.classList.add('action');
      this._updateStatus(instructions[challenge] || 'Look at the camera', stepLabel);
      this._updateProgress(((i) / total) * 80);

      if (this.isMediaPipeReady && this.faceLandmarker) {
        await this._detectGestureWithMediaPipe(challenge, instructions[challenge]);
      } else {
        // Fallback for environments without MediaPipe
        await new Promise(resolve => setTimeout(resolve, 2500));
      }

      this.completedChallenges.push(challenge);
      this._updateProgress(((i + 1) / total) * 80);
    }

    this.ovalElement.classList.remove('action', 'error');
    this.ovalElement.classList.add('valid');
    this._updateStatus('✔ Liveness checks completed!', 'COMPLETE');
    this._updateProgress(90);
    await new Promise(resolve => setTimeout(resolve, 600));
  }

  /**
   * MediaPipe real-time gesture detector for a specific challenge.
   */
  _detectGestureWithMediaPipe(challenge, defaultInstruction) {
    return new Promise((resolve) => {
      let hasClosedEyes = false; // State machine helper for blink
      const startTime = performance.now();
      const MAX_TIMEOUT_MS = 12000; // Safety fallback timeout

      const processFrame = () => {
        if (!this.stream || !this.videoElement) {
          resolve();
          return;
        }

        const elapsed = performance.now() - startTime;
        if (elapsed > MAX_TIMEOUT_MS) {
          console.warn(`[TrueFace SDK] Challenge timeout reached for ${challenge}, proceeding.`);
          resolve();
          return;
        }

        const results = this.faceLandmarker.detectForVideo(this.videoElement, performance.now());
        const count = results.faceLandmarks ? results.faceLandmarks.length : 0;

        if (count > 1) {
          // Halt gesture detection if multiple faces are detected!
          this.ovalElement.classList.remove('valid', 'action');
          this.ovalElement.classList.add('error');
          this._updateStatus('⚠️ Multiple faces detected. Only 1 face allowed.', 'MULTIPLE FACES');
          this.animFrameId = requestAnimationFrame(processFrame);
          return;
        } else if (count === 0) {
          this.ovalElement.classList.remove('valid', 'error');
          this.ovalElement.classList.add('action');
          this._updateStatus('No face detected. Look at the camera', 'NO FACE');
          this.animFrameId = requestAnimationFrame(processFrame);
          return;
        }

        // Single face detected
        this.ovalElement.classList.remove('error');
        this.ovalElement.classList.add('action');

        const landmarks = results.faceLandmarks[0];
        const pos = this._evaluateFacePosition(landmarks);

        if (!pos.isGood) {
          this._updateStatus(pos.hint);
        } else {
          this._updateStatus(defaultInstruction);
        }

        const ear = this._calcEAR(landmarks);
        const smileRatio = this._calcSmileRatio(landmarks);
        const yaw = this._calcYaw(landmarks);
        const mar = this._calcMAR(landmarks);

        // Stream real-time frame telemetry to Go gRPC Service
        this._sendGrpcFrame(ear, smileRatio, yaw, mar);

        let detected = false;
        if (challenge === 'blink') {
          if (ear < 0.18) {
            hasClosedEyes = true;
          } else if (hasClosedEyes && ear > 0.22) {
            detected = true;
          }
        } else if (challenge === 'smile') {
          if (smileRatio > 0.45) {
            detected = true;
          }
        } else if (challenge === 'openMouth') {
          if (mar > 0.35) {
            detected = true;
          }
        } else if (challenge === 'turnLeft') {
          if (yaw > 0.62) {
            detected = true;
          }
        } else if (challenge === 'turnRight') {
          if (yaw < 0.38) {
            detected = true;
          }
        }

        if (detected) {
          this._updateStatus(`✔ ${challenge.toUpperCase()} DETECTED!`);
          this.ovalElement.classList.remove('action', 'error');
          this.ovalElement.classList.add('valid');
          setTimeout(resolve, 400);
          return;
        }

        this.animFrameId = requestAnimationFrame(processFrame);
      };

      processFrame();
    });
  }

  // --- Landmark Math & Guidance Helpers ---

  _dist(p1, p2) {
    return Math.hypot(p1.x - p2.x, p1.y - p2.y);
  }

  _evaluateFacePosition(landmarks) {
    const nose = landmarks[1];
    const leftCheek = landmarks[234];
    const rightCheek = landmarks[454];
    const faceWidth = this._dist(leftCheek, rightCheek);

    if (faceWidth < 0.20) {
      return { isGood: false, hint: 'Move closer to the camera' };
    }
    if (faceWidth > 0.65) {
      return { isGood: false, hint: 'Move back a little' };
    }
    if (nose.x < 0.30 || nose.x > 0.70 || nose.y < 0.28 || nose.y > 0.72) {
      return { isGood: false, hint: 'Center your face in the oval' };
    }
    return { isGood: true, hint: null };
  }

  _checkFaceFramed(landmarks) {
    const nose = landmarks[1];
    const leftCheek = landmarks[234];
    const rightCheek = landmarks[454];
    const faceWidth = this._dist(leftCheek, rightCheek);

    // Nose must be roughly in the middle 40% of viewport
    const isCentered = nose.x > 0.30 && nose.x < 0.70 && nose.y > 0.30 && nose.y < 0.70;
    const isGoodSize = faceWidth >= 0.22 && faceWidth <= 0.65;

    return isCentered && isGoodSize;
  }

  async _initWasm() {
    if (this.wasmInstance) return;
    try {
      if (typeof TRUEFACE_WASM_BASE64 !== 'undefined') {
        const bin = atob(TRUEFACE_WASM_BASE64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        const module = await WebAssembly.instantiate(bytes, {
          env: { abort: () => console.error('[TrueFace WASM] Aborted') },
          wbg: {
            __wbindgen_throw: () => console.error('[TrueFace WASM Error]')
          }
        });
        this.wasmInstance = module.instance;
        console.log('[TrueFace SDK] 🚀 Native WebAssembly Core Module initialized!');
      }
    } catch (e) {
      console.warn('[TrueFace SDK] WebAssembly initialization fallback:', e);
    }
  }

  _calcEAR(landmarks) {
    if (this.wasmInstance && this.wasmInstance.exports.calc_ear) {
      return this.wasmInstance.exports.calc_ear(
        landmarks[159].x, landmarks[159].y, landmarks[145].x, landmarks[145].y,
        landmarks[33].x, landmarks[33].y, landmarks[133].x, landmarks[133].y,
        landmarks[386].x, landmarks[386].y, landmarks[374].x, landmarks[374].y,
        landmarks[362].x, landmarks[362].y, landmarks[263].x, landmarks[263].y
      );
    }
    const earLeft = this._dist(landmarks[159], landmarks[145]) / this._dist(landmarks[33], landmarks[133]);
    const earRight = this._dist(landmarks[386], landmarks[374]) / this._dist(landmarks[362], landmarks[263]);
    return (earLeft + earRight) / 2;
  }

  _calcSmileRatio(landmarks) {
    const mouthWidth = this._dist(landmarks[61], landmarks[291]);
    const faceWidth = this._dist(landmarks[234], landmarks[454]);
    return mouthWidth / faceWidth;
  }

  _calcMAR(landmarks) {
    if (this.wasmInstance && this.wasmInstance.exports.calc_mar) {
      return this.wasmInstance.exports.calc_mar(
        landmarks[13].x, landmarks[13].y, landmarks[14].x, landmarks[14].y,
        landmarks[61].x, landmarks[61].y, landmarks[291].x, landmarks[291].y
      );
    }
    const topLip = landmarks[13];
    const bottomLip = landmarks[14];
    const leftCorner = landmarks[61];
    const rightCorner = landmarks[291];
    const vertical = this._dist(topLip, bottomLip);
    const horizontal = this._dist(leftCorner, rightCorner) || 1;
    return vertical / horizontal;
  }

  _calcYaw(landmarks) {
    if (this.wasmInstance && this.wasmInstance.exports.calc_yaw) {
      return this.wasmInstance.exports.calc_yaw(landmarks[1].x, landmarks[234].x, landmarks[454].x);
    }
    const nose = landmarks[1];
    const leftFace = landmarks[234];
    const rightFace = landmarks[454];
    return (nose.x - leftFace.x) / (rightFace.x - leftFace.x);
  }

  /**
   * Confirms the user is looking straight ahead at the camera with eyes open
   * before completing the session and taking the final high-res selfie snapshot.
   */
  async _waitForStraightFace() {
    if (!this.isMediaPipeReady || !this.faceLandmarker) {
      this._updateStatus('Look straight at the camera', 'FINAL SNAPSHOT');
      await new Promise(resolve => setTimeout(resolve, 1000));
      return;
    }

    this.ovalElement.classList.remove('action', 'error');
    this.ovalElement.classList.add('valid');
    this._updateStatus('Look straight at the camera', 'FINAL SNAPSHOT');

    return new Promise((resolve) => {
      let straightFramesCount = 0;
      const startTime = performance.now();
      const MAX_TIMEOUT_MS = 6000;

      const checkStraight = () => {
        if (!this.stream || !this.videoElement) {
          resolve();
          return;
        }

        const elapsed = performance.now() - startTime;
        if (elapsed > MAX_TIMEOUT_MS) {
          console.warn('[TrueFace SDK] Straight face alignment timeout reached, proceeding with snapshot.');
          resolve();
          return;
        }

        const results = this.faceLandmarker.detectForVideo(this.videoElement, performance.now());
        const count = results.faceLandmarks ? results.faceLandmarks.length : 0;

        if (count > 1) {
          this.ovalElement.classList.remove('valid', 'action');
          this.ovalElement.classList.add('error');
          this._updateStatus('⚠️ Multiple faces detected. Only 1 face allowed.', 'MULTIPLE FACES');
          straightFramesCount = 0;
        } else if (count === 0) {
          this.ovalElement.classList.remove('valid', 'error');
          this.ovalElement.classList.add('action');
          this._updateStatus('Look straight at the camera', 'FINAL SNAPSHOT');
          straightFramesCount = 0;
        } else {
          const landmarks = results.faceLandmarks[0];
          const pos = this._evaluateFacePosition(landmarks);
          const yaw = this._calcYaw(landmarks);
          const ear = this._calcEAR(landmarks);

          // Head must be centered (yaw between 0.44 and 0.56) and eyes open (EAR >= 0.19)
          const isLookingStraight = yaw >= 0.44 && yaw <= 0.56;
          const isEyesOpen = ear >= 0.19;

          if (!pos.isGood) {
            this.ovalElement.classList.remove('valid', 'action');
            this.ovalElement.classList.add('error');
            this._updateStatus(pos.hint, 'ALIGNMENT');
            straightFramesCount = 0;
          } else if (!isLookingStraight) {
            this.ovalElement.classList.remove('valid', 'action');
            this.ovalElement.classList.add('error');
            this._updateStatus('Look straight at the camera', 'LOOK STRAIGHT');
            straightFramesCount = 0;
          } else if (!isEyesOpen) {
            this.ovalElement.classList.remove('error', 'action');
            this.ovalElement.classList.add('valid');
            this._updateStatus('Keep your eyes open', 'LOOK STRAIGHT');
            straightFramesCount = 0;
          } else {
            this.ovalElement.classList.remove('error', 'action');
            this.ovalElement.classList.add('valid');
            this._updateStatus('✔ Face centered! Capturing photo...', 'CAPTURING');
            straightFramesCount++;

            // Must hold straight pose for 8 consecutive frames (~250-300ms) for a clean snapshot
            if (straightFramesCount >= 8) {
              this._captureSelfieSnapshot();
              setTimeout(resolve, 100);
              return;
            }
          }
        }

        this.animFrameId = requestAnimationFrame(checkStraight);
      };

      checkStraight();
    });
  }

  _captureSelfieSnapshot() {
    if (this.videoElement && this.videoElement.videoWidth > 0 && this.videoElement.srcObject) {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = this.videoElement.videoWidth || 640;
        canvas.height = this.videoElement.videoHeight || 480;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(this.videoElement, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.92);
        this.capturedImageBase64 = dataUrl.replace(/^data:image\/jpeg;base64,/, '');
        console.log('[TrueFace SDK] High-res selfie photo captured successfully.');
      } catch (e) {
        console.warn('[TrueFace SDK] Error capturing selfie photo:', e);
      }
    }
  }

  _showProcessingUI() {
    if (this.processingCardElement) return;

    this.processingCardElement = document.createElement('div');
    this.processingCardElement.className = 'trueface-processing-card';
    this.processingCardElement.innerHTML = `
      <div class="trueface-spinner"></div>
      <div class="trueface-processing-title">Processing Verification</div>
      <div class="trueface-processing-sub">Uploading biometric scans & verifying security proof...</div>
    `;

    if (this.overlayElement) {
      this.overlayElement.appendChild(this.processingCardElement);
    }
  }

  _showOutcomeUI(result) {
    if (this.processingCardElement) {
      this.processingCardElement.remove();
      this.processingCardElement = null;
    }

    const outcomeCard = document.createElement('div');
    outcomeCard.className = 'trueface-outcome-card';

    const isApproved = result && (result.status === 'approved' || result.status === 'completed' || result.status === 'processing');
    const isRejected = result && (result.status === 'rejected' || result.status === 'failed');

    let iconHtml = '<div class="trueface-outcome-icon valid">✔</div>';
    let titleText = 'Verification Complete';
    let subText = 'Your biometric liveness check passed successfully.';

    if (isRejected) {
      iconHtml = '<div class="trueface-outcome-icon error">✖</div>';
      titleText = 'Verification Unsuccessful';
      subText = result.decisionReason || result.reason || 'Biometric liveness check did not pass.';
    }

    outcomeCard.innerHTML = `
      ${iconHtml}
      <div class="trueface-outcome-title">${titleText}</div>
      <div class="trueface-outcome-sub">${subText}</div>
    `;

    if (this.overlayElement) {
      this.overlayElement.appendChild(outcomeCard);
    }
  }

  _stopCameraStream() {
    if (this.animFrameId) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
    if (this.stream) {
      this.stream.getTracks().forEach(track => track.stop());
      this.stream = null;
    }
    if (this.videoElement) {
      this.videoElement.srcObject = null;
    }
  }

  async _finalizeAndUpload() {
    // 1. Ensure selfie photo snapshot is captured
    if (!this.capturedImageBase64) {
      this._captureSelfieSnapshot();
    }
    const finalImageBase64 = this.capturedImageBase64 || "";

    // 2. Stop video recording and compile full video base64
    if (this.mediaRecorder && this.mediaRecorder.state !== 'inactive') {
      this.mediaRecorder.stop();
      await new Promise(resolve => {
        this.mediaRecorder.onstop = resolve;
      });
    }

    // 3. Immediately stop camera hardware stream so webcam light turns off during upload
    this._stopCameraStream();

    let finalVideoBase64 = "";
    if (this.recordedChunks && this.recordedChunks.length > 0) {
      try {
        const videoBlob = new Blob(this.recordedChunks, { type: 'video/webm' });
        const videoArrayBuffer = await videoBlob.arrayBuffer();
        const videoBytes = new Uint8Array(videoArrayBuffer);
        let videoBinary = '';
        const CHUNK_SIZE = 0x8000;
        for (let i = 0; i < videoBytes.length; i += CHUNK_SIZE) {
          videoBinary += String.fromCharCode.apply(null, videoBytes.subarray(i, i + CHUNK_SIZE));
        }
        finalVideoBase64 = btoa(videoBinary);
      } catch (e) {
        console.warn('[TrueFace SDK] Error encoding recorded video:', e);
      }
    }

    // 4. Complete gRPC session with BOTH final selfie image AND complete recorded video!
    await this._completeGrpcSession(finalImageBase64, finalVideoBase64);

    if (this.grpcProofToken && this.imageKey && this.videoKey) {
      console.log('[TrueFace SDK] Server-side S3 media processing complete via gRPC:', this.imageKey, this.videoKey);
      return;
    }

    // 5. No client-side S3 fallback allowed. If gRPC stream is incomplete, throw to trigger challenge restart
    throw new Error('LIVENESS_CHALLENGES_INCOMPLETE');
  }

  async _completeVerification() {
    const payload = {
      imageKey: this.imageKey,
      videoKey: this.videoKey,
      completedChallenges: this.completedChallenges,
      proofToken: this.grpcProofToken,
      clientSecret: this.clientSecret,
      deviceOs: 'web',
      deviceModel: navigator.userAgent
    };

    const encryptedBody = await this._encryptPayload(JSON.stringify(payload), this.clientSecret);

    const res = await fetch(`${this.backendBaseUrl}/v1/sessions/${this.verificationId}/complete`, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-public-key': this.publicKey,
        'x-client-secret': this.clientSecret
      },
      body: JSON.stringify(encryptedBody)
    });

    if (!res.ok) throw new Error(`Verification processing failed (${res.status})`);
    return await res.json();
  }

  async _encryptPayload(plainText, secret) {
    const encoder = new TextEncoder();
    const paddedSecret = secret.padEnd(32, ' ').substring(0, 32);
    const keyData = encoder.encode(paddedSecret);

    const key = await window.crypto.subtle.importKey(
      'raw',
      keyData,
      { name: 'AES-CBC' },
      false,
      ['encrypt']
    );

    const iv = window.crypto.getRandomValues(new Uint8Array(16));
    const encryptedData = await window.crypto.subtle.encrypt(
      { name: 'AES-CBC', iv: iv },
      key,
      encoder.encode(plainText)
    );

    const base64Data = btoa(String.fromCharCode(...new Uint8Array(encryptedData)));
    const base64Iv = btoa(String.fromCharCode(...iv));

    return {
      encryptedData: base64Data,
      iv: base64Iv
    };
  }

  _showError(msg) {
    if (this.container) {
      const errEl = document.createElement('div');
      errEl.className = 'trueface-error-banner';
      errEl.textContent = `Error: ${msg}`;
      this.container.appendChild(errEl);
      setTimeout(() => errEl.remove(), 4000);
    }
  }
}

// Attach globally
window.TrueFaceLiveness = TrueFaceLiveness;
